-- mod-dnd: strip the world down to what the D&D rules use (generated by tools/make_world_sql.py)

-- quests: all gone, bespoke ones come later
DELETE FROM `creature_queststarter`;
DELETE FROM `creature_questender`;
DELETE FROM `gameobject_queststarter`;
DELETE FROM `gameobject_questender`;

-- friendly folk are ordinary people in D&D terms: nobody in the starting lands shows a "god-tier" level 30+
UPDATE `creature_template` ct
  JOIN (SELECT DISTINCT `id` FROM `creature` WHERE `map` IN (0, 1) AND `guid` < 9000000) c ON c.`id` = ct.`entry`
   SET ct.`minlevel` = LEAST(ct.`minlevel`, 5), ct.`maxlevel` = LEAST(ct.`maxlevel`, 5), ct.`rank` = 0
 WHERE ct.`faction` IN (11, 12, 55, 57, 64, 875, 1078, 35, 1077, 1094, 1097) OR ct.`npcflag` <> 0;

-- vendors sell nothing; no repairs (no durability)
DELETE FROM `npc_vendor`;
UPDATE `creature_template` SET `npcflag` = `npcflag` & ~8066;
UPDATE `creature` SET `npcflag` = `npcflag` & ~8066 WHERE `npcflag` <> 0;

-- class and pet trainers: classes level through the D&D system instead
UPDATE `creature_template` ct
  JOIN `creature_default_trainer` cdt ON cdt.`CreatureId` = ct.`entry`
  JOIN `trainer` t ON t.`Id` = cdt.`TrainerId`
   SET ct.`npcflag` = ct.`npcflag` & ~48
 WHERE t.`Type` IN (0, 3);

-- loot and money: encounters get bespoke drops
DELETE FROM `creature_loot_template`;
DELETE FROM `pickpocketing_loot_template`;
DELETE FROM `skinning_loot_template`;
UPDATE `creature_template` SET `lootid` = 0, `pickpocketloot` = 0, `skinloot` = 0, `mingold` = 0, `maxgold` = 0;

-- nothing regenerates on its own
UPDATE `creature_template` SET `RegenHealth` = 0;

