-- townsfolk (tools/townsfolk.py): WoW-only NPCs leave Dun Morogh; seasonal event crowds too
DELETE c FROM `creature` c JOIN `creature_template` t ON t.`entry` = c.`id`
 WHERE c.`map` = 0 AND ((c.`position_x` BETWEEN -6500 AND -4700 AND c.`position_y` BETWEEN -2700 AND 1000 AND NOT (c.`position_x` > -5080 AND c.`position_y` < -620)) OR (c.`position_x` BETWEEN -5960 AND -4600 AND c.`position_y` BETWEEN -4450 AND -2400) OR (c.`position_x` BETWEEN -4150 AND -2250 AND c.`position_y` BETWEEN -3700 AND -450) OR (c.`position_x` BETWEEN -2300 AND -550 AND c.`position_y` BETWEEN -4000 AND -1450) OR (c.`position_x` BETWEEN -7150 AND -6300 AND c.`position_y` BETWEEN -2050 AND -450) OR (c.`position_x` BETWEEN -5080 AND -4550 AND c.`position_y` BETWEEN -1330 AND -845) OR (c.`position_x` BETWEEN -9120 AND -8250 AND c.`position_y` BETWEEN 260 AND 1450) OR (c.`position_x` BETWEEN -10120 AND -8650 AND c.`position_y` BETWEEN -1350 AND 950)) AND c.`guid` < 9000000
   AND (c.`id` IN (895,916,944,926,912,2878,460,837,1355,1701,4772,1241,1700,1702,9980,26007,26760,26012,39678,39349,39263,39711,39715,39716,39717,39396,39420,39368,39386,39675,39275,15127,15130,14983,14984,15124,26724,26738,26739,26740,26741,26742,26743,26744,26745,26747,26748,26749,26751,26752,26753,26754,26755,26756,26757,26758,26759,26765,26307,26309,26324,26325,26326,26327,26328,26329,26330,26331,26332,26075) OR t.`subname` LIKE '%Trainer%' OR t.`subname` LIKE '%Battlemaster%'
        OR t.`subname` = 'Stable Master');
DELETE c FROM `creature` c JOIN `game_event_creature` g ON g.`guid` = c.`guid`
 WHERE c.`map` = 0 AND ((c.`position_x` BETWEEN -6500 AND -4700 AND c.`position_y` BETWEEN -2700 AND 1000 AND NOT (c.`position_x` > -5080 AND c.`position_y` < -620)) OR (c.`position_x` BETWEEN -5960 AND -4600 AND c.`position_y` BETWEEN -4450 AND -2400) OR (c.`position_x` BETWEEN -4150 AND -2250 AND c.`position_y` BETWEEN -3700 AND -450) OR (c.`position_x` BETWEEN -2300 AND -550 AND c.`position_y` BETWEEN -4000 AND -1450) OR (c.`position_x` BETWEEN -7150 AND -6300 AND c.`position_y` BETWEEN -2050 AND -450) OR (c.`position_x` BETWEEN -5080 AND -4550 AND c.`position_y` BETWEEN -1330 AND -845) OR (c.`position_x` BETWEEN -9120 AND -8250 AND c.`position_y` BETWEEN 260 AND 1450) OR (c.`position_x` BETWEEN -10120 AND -8650 AND c.`position_y` BETWEEN -1350 AND 950)) AND c.`guid` < 9000000;
