-- no respawning herbs, ore or treasure chests
DELETE g FROM `gameobject` g
  JOIN `gameobject_template` t ON t.`entry` = g.`id`
 WHERE g.`map` IN (0, 1) AND g.`guid` < 9000000 AND t.`type` = 3;
