-- no holidays: WoW's game events follow the real calendar (Winter Veil, Hallow's End, Love is in the Air, the Darkmoon
-- Faire, battleground weekends, fishing contests, invasions...) and bring stock NPCs, items and quests that aren't D&D's.
-- Every one is switched off for good: a window that closed in 2000. (What spawns only while an event is off - the usual
-- guards and the like - stays as it is.)
UPDATE `game_event` SET `start_time` = '2000-01-01 00:00:00', `end_time` = '2000-01-01 00:00:01';

-- class spells and action bars come from mod-dnd
DELETE FROM `playercreateinfo_action`;

-- everyone starts in Coldridge Valley (the dwarves' spot), whatever their race; death knights keep Ebon Hold
UPDATE `playercreateinfo` SET `map` = 0, `zone` = 1, `position_x` = -6240.32, `position_y` = 331.033,
  `position_z` = 382.758, `orientation` = 6.17716 WHERE `class` <> 6;

-- items: no level requirements
UPDATE `item_template` SET `RequiredLevel` = 0;

-- starter gear, D&D style. Body armour 'armor' >= 10 is a base AC; weapons store dice as min = count, max = count*sides.
